reak; // 普通素人\n        case 4:\n            base = 70;\n            break; // 玩得多的\n        case 5:\n            base = 80;\n            break; // 职业者\n        default: base = 60;\n    }\n    // 年龄修正：越年长越难被取悦（但 36+ 反而松一些，因为更知道自己要什么）\n    if (年龄 < 24)\n        base -= 5;\n    else if (年龄 >= 36)\n        base += 5;\n    return Math.max(20, Math.min(95, base));\n}\n// ══════════════════════════════════════════\n// ★★★ 外貌 v2 合成器\n//   五官 20 轴 / 穿搭 12 轴 / 私处 23 轴 / 性病多维叠加\n//\n// 四条铁律：\n//   ① 每根轴都必须在代码里抽，且分布被设计过（不是均匀，更不是常量）\n//   ② 性病是【数组】：0..3 条，可同时叠加（HIV+梅毒、淋病+衣原体、疱疹+BV…）\n//   ③ 体征必须真实对应病种（不许张冠李戴）；病名只许出现在 病种，\n//      【绝不许】写进 阴部 那句话里\n//   ④ 治愈后：离开 性病[]，进入 病痕[] + 免疫记忆[]（轴仍在，不删证据）\n// ══════════════════════════════════════════\n/** ★ 五官 20 轴：逐字段抽真值（库名 → 字段名 见 schema.ts L706-730） */\nfunction 合成五官() {\n    return {\n        脸型: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"脸型库\"]),\n        眼型: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"眼型库\"]),\n        瞳色: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"瞳色库\"]),\n        眼妆: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"眼妆库\"]),\n        眉毛: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"眉毛库\"]),\n        鼻型: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"鼻型库\"]),\n        唇型: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"唇型库\"]),\n        唇色: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"唇色库\"]),\n        牙齿: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"牙齿库\"]),\n        下巴: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"下巴库\"]),\n        耳型: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"耳型库\"]),\n        脖型: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"脖型库\"]),\n        素颜感: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"素颜感库\"]),\n        妆感: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"妆感库\"]),\n        发型: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"发型库\"]),\n        发色: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"发色库\"]),\n        发质: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"发质库\"]),\n        发长: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"发长库\"]),\n        声线印象: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"声线印象库\"]),\n        惯常表情: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"惯常表情库\"]),\n    };\n}\n/** ★ 穿搭 12 轴（唯一允许 AI 每回合改的一组；生成时同样必须逐字段给真值） */\nfunction 合成穿搭() {\n    return {\n        上装: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"上装库\"]),\n        下装: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"下装库\"]),\n        内衣: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"内衣库\"]),\n        内裤: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"内裤库\"]),\n        袜子: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"袜子库\"]),\n        鞋子: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"鞋子库\"]),\n        饰品: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"饰品库\"]),\n        妆容: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"妆容库\"]),\n        风格: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"穿搭风格库\"]),\n        暴露度: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"暴露度库\"]),\n        场合适配: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"场合适配库\"]),\n        破绽: 抽(___WEBPACK_IMPORTED_MODULE_0__[\"破绽库\"]),\n    };\n}\n/** 抽 [最少, 最多] 个不重复项（池子不够就全给） */\nfunction 抽区间(arr, 最少, 最多) {\n    const n = 最少 + Math.floor(Math.random() * (最多 - 最少 + 1));\n    return 抽N(arr, Math.min(n, arr.length));\n}\n/** 先过滤再抽：过滤后为空则回退到原池（绝不给 undefined） */\nfunction 合法池(池, 断言) {\n    const 筛 = 池.filter(断言);\n    return 筛.length > 0 ? 筛 : 池;\n}\nfunction 抽过滤(库, 断言) {\n    return 抽(合法池(库, 断言));\n}\n/**\n * ★ 病种指纹抽：优先从【该病种专属池】里抽，池子被污染/为空时才回退到全库。\n *   —— 这样分泌物四轴由病种决定（淋病必是脓性、念珠菌必是豆腐渣），\n *      而不是全库均匀抽（那会让体征与分泌物互相打架 = 张冠李戴）。\n */\nfunction 合法抽(优先池, 全库) {\n    const 干净 = 优先池.filter(x => 全库.includes(x));\n    return 抽(干净.length > 0 ? 干净 : 全库);\n}\n// ──────────────────────────────────────────\n// ★ 性病 · 多维叠加轴（见 _分析/I-性病多维叠加轴.md）\n//   四个正交维度：A 数量 × B 每条 15 子轴 × C 跨轴耦合 × D 叙事叠加\n// ──────────────────────────────────────────\n/** 医疗可及性分区：决定 `性病治疗库` 的真实分布（不是均匀抽） */\nconst 医疗高区 = ['日本', '韩国', '德国', '荷兰', '美国', '英国'];\nconst 医疗低区 = ['泰国', '印度', '中东', '哥伦比亚', '肯尼亚', '尼日利亚', '缅甸'];\n/** ★ 暴露线索池（她被人看见/自己撞见的瞬间） */\nconst 暴露线索池 = [\n    '洗澡时自己看到那一片不对',\n    '体检报告单被室友瞥见一眼',\n    '内裤裆部整片湿黄洗不掉',\n    '性伴事后追问“你下面是不是有问题”',\n    '买药时药盒从包里翻出来',\n    '同房时对方看到渗出物停下来',\n    '身上一股洗不掉的味被同事问起',\n    '月经垫上出现异常的颜色',\n    '药店店员多看了她一眼并劝她就医',\n    '合租室友共用马桶圈的抱怨',\n];\n/** ★ 来源对象池（感染链的另一端，大多是具体的人而不是抽象名词） */\nconst 来源对象池 = [\n    '前男友（分手后才知道他在外面乱来）',\n    '夜班酒吧认识的男人（名字没问）',\n    '会所客人（境外来的，只收现金）',\n    '线上约的炮友（事后删了微信）',\n    '丈夫（婚内传的，他不承认）',\n    '带她进圈的介绍人',\n    '同宿舍女生共用毛巾（说不清是谁）',\n    '前夫（复婚之后才查出）',\n    '包养她三个月的老板',\n    '夜场同行（共用器具）',\n    '一次没戴套的一夜情（连脸都记不清）',\n    '医学院的实习对象（她自己也说不清）',\n];\n/** ★ 共感染表：索引 = 性病库 下标，值 = 临床上真实会一起出现的其他病 */\nconst 性病共感染表 = [\n    [1, 19, 22, 10], // 0 淋病 → 衣原体 / 支原体 / 淋菌性咽炎 / 滴虫\n    [0, 19, 10, 11], // 1 衣原体\n    [20, 0, 1, 6], // 2 梅毒·一期（梅毒+HIV 是经典组合）\n    [20, 6, 8], // 3 梅毒·二期\n    [20, 2], // 4 梅毒·潜伏\n    [20], // 5 梅毒·三期\n    [11, 12, 2, 20], // 6 疱疹·原发\n    [6, 11, 20], // 7 疱疹·复发\n    [9, 20, 6], // 8 尖锐湿疣（低危 HPV 与高危 HPV 常共感染）\n    [8, 20, 6], // 9 高危 HPV\n    [0, 11, 19, 1], // 10 滴虫\n    [10, 12, 6, 1], // 11 细菌性阴道病\n    [6, 11, 20], // 12 念珠菌（真菌+细菌失衡）\n    [14, 20, 2], // 13 阴虱（阴虱与疥疮同床共传）\n    [13, 20], // 14 疥疮\n    [20, 9], // 15 传染性软疣\n    [20, 2, 0], // 16 软下疳\n    [20, 0, 1], // 17 LGV\n    [20, 16], // 18 腹股沟肉芽肿\n    [0, 1, 11, 10], // 19 支原体 / 解脲脲原体\n    [2, 3, 6, 0, 1, 9, 8], // 20 HIV（合并一切的枢纽）\n    [20, 0], // 21 乙型肝炎\n    [0, 20, 1], // 22 淋菌性咽炎 / 直肠炎\n    [12, 11], // 23 阴部硬化性苔藓 / VIN\n];\nconst 性病元数据表 = [\n    {\n        短名: '淋病',\n        病原: '淋病奈瑟菌（革兰阴性双球菌，黏膜柱状上皮定植）',\n        部位池: ['尿道口（阴蒂下方那个小孔）', '宫颈（深处那个圆钝的宫口）'],\n        体征池: [\n            '尿道口红肿外翻，边缘翻成唇状',\n            '排尿时刀割样剧痛，疼到不敢尿',\n            '宫颈充血脆性大，棉签一碰就出血',\n            '尿道口持续溢脓，内裤裆部整片湿黄',\n            '晨起尿道口被脓痂封住（糊口）',\n        ],\n        量池: ['中偏多（能抹开一整片）', '多（顺着会阴往下流）', '极多（一碰就涌）'],\n        色池: ['黄绿脓性', '微黄（久置氧化的黄）', '粘稠乳白'],\n        质池: ['奶浆状（乳白且浓）', '黏（拉出短丝）', '一接触空气就变黏变黄'],\n        味池: ['捂了一整天的闷热骚气', '尿骚混着汗酸（一天没洗）', '淡淡腥气'],\n        疼痛: [60, 85],\n        瘙痒: [10, 30],\n        传染性: '高（化脓性渗出物接触即传）',\n        痕迹池: [\n            '尿道反复发作留下的瘢痕性狭窄',\n            '宫颈旧炎留下的脆性出血面',\n            '内裤裆部与臀缝洗不掉的淡黄药渍',\n        ],\n        免疫: '淋病不产生保护性免疫，抗体不保护，可反复再感染',\n        易复发: false,\n        可治愈: true,\n        分期池: [